--
-- Struttura della tabella `clienti`
--

CREATE TABLE IF NOT EXISTS `clienti` (
  `codice_cliente` int(11) NOT NULL,
  `ragione_sociale` varchar(90) NOT NULL,
  `cognome_contatto` varchar(50) NOT NULL,
  `nome_contatto` varchar(50) NOT NULL,
  `telefono` varchar(50) NOT NULL,
  `indirizzo1` varchar(80) NOT NULL,
  `indirizzo2` varchar(80) DEFAULT NULL,
  `citta` varchar(50) NOT NULL,
  `stato_provincia` varchar(50) DEFAULT NULL,
  `codice_postale` varchar(15) DEFAULT NULL,
  `paese` varchar(50) NOT NULL,
  `referente_commerciale` int(11) DEFAULT NULL,
  `limite_credito` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`codice_cliente`),
  KEY `fk_clienti_dipendenti` (`referente_commerciale`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

