--
-- Struttura della tabella `dettagli_ordini`
--

CREATE TABLE IF NOT EXISTS `dettagli_ordini` (
  `numero_ordine` int(11) NOT NULL,
  `codice_prodotto` varchar(15) NOT NULL,
  `quantita_ordinata` int(11) NOT NULL,
  `prezzo_unitario` decimal(10,2) NOT NULL,
  `numero_riga_ordine` smallint(6) NOT NULL,
  PRIMARY KEY (`numero_ordine`,`codice_prodotto`),
  KEY `fk_dettagli_ordini_prodotti` (`codice_prodotto`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

