CREATE TABLE IF NOT EXISTS `linee_prodotto` (
  `linea_prodotto` varchar(50) NOT NULL,
  `descrizione_testuale` varchar(4000) DEFAULT NULL,
  `descrizione_html` mediumtext DEFAULT NULL,
  `immagine` mediumblob DEFAULT NULL,
  PRIMARY KEY (`linea_prodotto`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dump dei dati per la tabella `linee_prodotto`
--

INSERT INTO `linee_prodotto` (`linea_prodotto`, `descrizione_testuale`, `descrizione_html`, `immagine`) VALUES
('Aerei', 'Riproduzioni di aerei ed elicotteri in metallo pressofuso, utili per simulare vendite e classificazioni per linea prodotto.', NULL, NULL),
('Auto classiche', 'Riproduzioni in scala di automobili classiche pensate per collezionisti, esercitazioni di catalogazione prodotti e analisi del magazzino.', NULL, NULL),
('Auto d\'epoca', 'Riproduzioni di automobili storiche prodotte nei primi decenni del Novecento, pensate per collezionisti e analisi di vendita.', NULL, NULL),
('Camion e autobus', 'Riproduzioni di camion, autobus e veicoli commerciali, con varianti di scala e prezzo per esercitazioni SQL.', NULL, NULL),
('Motociclette', 'Modelli di motociclette da collezione con dettagli realistici, adatti a ordini, listini e gestione delle disponibilità.', NULL, NULL),
('Navi', 'Modelli navali da esposizione, adatti a cataloghi commerciali, gestione ordini e analisi dei prezzi di listino.', NULL, NULL),
('Treni', 'Modelli ferroviari e locomotori da collezione, utili per esercizi su prodotti, fornitori e giacenze.', NULL, NULL);

