--
-- Struttura della tabella `prodotti`
--

CREATE TABLE IF NOT EXISTS `prodotti` (
  `codice_prodotto` varchar(15) NOT NULL,
  `nome_prodotto` varchar(70) NOT NULL,
  `linea_prodotto` varchar(50) NOT NULL,
  `scala_prodotto` varchar(10) NOT NULL,
  `fornitore_prodotto` varchar(80) NOT NULL,
  `descrizione_prodotto` text NOT NULL,
  `quantita_magazzino` smallint(6) NOT NULL,
  `prezzo_acquisto` decimal(10,2) NOT NULL,
  `prezzo_listino` decimal(10,2) NOT NULL,
  PRIMARY KEY (`codice_prodotto`),
  KEY `fk_prodotti_linee_prodotto` (`linea_prodotto`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

