  `codice_ufficio` varchar(10) NOT NULL,
  `citta` varchar(50) NOT NULL,
  `telefono` varchar(50) NOT NULL,
  `indirizzo1` varchar(80) NOT NULL,
  `indirizzo2` varchar(80) DEFAULT NULL,
  `stato_provincia` varchar(50) DEFAULT NULL,
  `paese` varchar(50) NOT NULL,
  `codice_postale` varchar(15) NOT NULL,
  `territorio` varchar(50) NOT NULL,
  PRIMARY KEY (`codice_ufficio`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

